// A ring built from Julia sets. Going around the ring, each slice through it is the Julia set for
// a point on the edge of the Mandelbrot set's main cardioid. The ring is ray marched, with a wedge
// cut out of it to show the slices, and the cut faces reflect a gradient sky.
// The camera and the cut follow the timeline: try changing a row, or [twist] on its own.
#define tilt iFloat0     // How far the ring tips towards the camera.
#define turn iFloat1     // The ring's turn about its axis, in quarter turns.
#define twist iFloat2    // How many times the Julia sets go around the ring.
#define cut iFloat3      // How wide the wedge cut out of the ring is.
#define closeUp iFloat4  // Moves the camera in close to the cut faces.

#define PI 3.14159265

vec3 rotate(vec3 p, vec3 axis, float angle) {
  axis = normalize(axis);
  return mix(dot(axis, p) * axis, p, cos(angle)) - sin(angle) * cross(axis, p);
}

// The point on the edge of the main cardioid at angle a.
vec2 cardioid(float a) {
  vec2 c = -vec2(cos(a), sin(a)) * (1. + cos(a)) / 2.;
  return c + vec2(0.2499, 0.);
}

// Distance from z to the Julia set for c, estimated from how fast z escapes.
float juliaDist(vec2 z, vec2 c) {
  vec2 dz = vec2(1., 0.);
  for (int i = 0; i < 100; i++) {
    if (dot(z, z) > 32.) {
      return 0.5 * sqrt(dot(z, z) / dot(dz, dz)) * log(dot(z, z));
    }
    dz = 2. * vec2(z.x * dz.x - z.y * dz.y, z.x * dz.y + z.y * dz.x);
    z = vec2(z.x * z.x - z.y * z.y, 2. * z.x * z.y) + c;
  }
  return 0.;
}

// The ring: the slice at each angle around the y axis is a Julia set, 4 from the centre.
float ringDist(vec3 p) {
  vec2 slice = vec2(length(p.xz) - 4., p.y);
  return juliaDist(slice, cardioid(atan(p.x, p.z) - 2. * PI * twist));
}

// The wedge cut out of the ring, between two planes through its axis.
float wedgeDist(vec3 p) {
  float back = 2.5;
  float front = back - 1.5 * cut;
  vec3 n1 = vec3(sin(front + PI), 0., cos(front + PI));
  vec3 n2 = vec3(sin(back), 0., cos(back));
  return max(dot(p, n1), dot(p, n2));
}

float scene(vec3 pos, out bool onCut) {
  vec3 p = rotate(pos, vec3(1., 0., 0.), 0.4 + 0.2 * tilt);
  p = rotate(p, vec3(0., 1., 0.), 0.5 * PI * turn);
  float ring = ringDist(p);
  float wedge = -wedgeDist(p);
  onCut = wedge > ring;
  return max(ring, wedge);
}

vec3 sceneNormal(vec3 p, float d) {
  bool unused;
  float eps = 0.1;
  return normalize(vec3(
    scene(p + vec3(eps, 0., 0.), unused),
    scene(p + vec3(0., eps, 0.), unused),
    scene(p + vec3(0., 0., eps), unused)) - d);
}

// The sky the cut faces reflect: a glowing horizon between a deep blue zenith and a dark floor,
// with its hue drifting around the horizon.
vec3 sky(vec3 dir) {
  vec3 horizon = vec3(1., 0.55, 0.3);
  vec3 col = dir.y > 0.
    ? mix(horizon, vec3(0.08, 0.15, 0.55), pow(dir.y, 0.4))
    : mix(horizon, vec3(0.12, 0.04, 0.18), pow(-dir.y, 0.3));
  float around = atan(dir.z, dir.x);
  return col * (0.75 + 0.25 * cos(3. * around + vec3(0., 2., 4.)));
}

// The colour of a point on the ring: the cut faces reflect the photo, and the ring's surface is
// lit by one light.
vec3 shade(vec3 p, float d, bool onCut, vec3 dir) {
  vec3 n = sceneNormal(p, d);
  if (onCut) {
    return 1.2 * sky(reflect(dir, n));
  }
  vec4 light = vec4(3., 2., 4., 9.);
  vec3 toLight = light.xyz - p;
  float falloff = 1. - pow(min(1., length(toLight) / light.w), 2.);
  return vec3(2. * max(0., dot(n, normalize(toLight))) * falloff);
}

vec3 trace(vec3 origin, vec3 dir) {
  vec3 p = origin;
  bool onCut = false;
  float d = 1.;
  // The distance estimate overshoots near the set, so march a fraction of it.
  float stepScale = 0.45 + 0.17 * closeUp;
  for (int i = 0; i < 160; i++) {
    d = scene(p, onCut);
    // Further away, a pixel covers more of the ring, so it needn't get as close.
    if (d < 0.0005 * length(p - origin)) {
      break;
    }
    p += stepScale * d * dir;
  }
  // A ray that ran out of steps close to the ring still lands on it, rather than leaving a speck.
  return d < 0.01 ? shade(p, d, onCut, dir) : vec3(0.);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec3 origin = mix(vec3(0., 0., 9.5), vec3(2., -2.5, 3.8), closeUp);
  // Four rays around the pixel and two through its centre, to smooth the edges.
  vec3 col = vec3(0.);
  for (int i = 0; i <= 4; i++) {
    float a = 0.2 + 2. * PI * float(i + 1) / 4.;
    vec2 offset = i < 4 ? 0.6 * vec2(cos(a), sin(a)) : vec2(0.);
    vec2 uv = 0.7 * (2. * (fragCoord + offset) - iResolution.xy) / iResolution.y;
    vec3 dir = normalize(vec3(uv, -1.));
    dir = rotate(dir, vec3(0., 1., 0.), 0.5 * closeUp);
    dir = rotate(dir, vec3(1., 0., 0.), -0.5 * closeUp);
    col += (i < 4 ? 1. : 2.) * trace(origin, dir);
  }
  fragColor = vec4(col / 6., 1.);
}
